/* batch42recorder: Sync settings tab strip (Notes/Calendar/Album/Recorder).
   Boxes are fixed-width (80+56+56+68=260px) but the pill is only 251px,
   so "Recorder" hangs outside. Pill widened to fit the boxes. */
[data-v-fc27b3a4] .tab-has-recorder .vivo-tab-nav{width:272px!important}
[data-v-fc27b3a4] .tab-has-recorder .vivo-tab-nav .vivo-tab-nav-item:last-child{-webkit-box-flex:78px!important;-webkit-flex:78px 0 0!important;-ms-flex:78px 0 0!important;flex:78px 0 0!important;white-space:nowrap}

/* batch22c: labels EN du Go to date plus larges que les colonnes -> wrap sous la pilule 50px -> chevauchement des boutons. */
.dialog-middle[data-v-f20bebaa] .vivo-dialog-body .item-content .textCss{font-size:15px}
.dialog-middle[data-v-f20bebaa] .vivo-dialog-body .item-content .year,.dialog-middle[data-v-f20bebaa] .vivo-dialog-body .item-content .month,.dialog-middle[data-v-f20bebaa] .vivo-dialog-body .item-content .day{white-space:nowrap}

/* batch29album: "Recently deleted" coupe au milieu des mots dans le rail de 180px (word-break:break-all). Rail elargi a 210px, noms d album sur une ligne avec ellipsis (infobulle JS au survol pour les noms longs). */
.album-left-bar-container[data-v-97718154]{width:210px}
.album-left-bar-container .add-wrap[data-v-97718154]{width:210px}
.album-left-bar-container .add-wrap .add-box[data-v-97718154]{width:170px}
.album-left-bar-container .album-container-menu[data-v-97718154]{width:210px}
.back-box[data-v-97718154]{width:210px}
.link .folder-name[data-v-97718154]{display:block;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;word-break:normal}

/* batch29reminder: les libelles EN ("15 minutes before"...) tiennent sur 2 lignes dans un item de 40px fixe -> les lignes se chevauchent. Le popover passe a 200px (patch 8.js) ; les items grandissent si besoin et le titre reste sur une ligne. */
.reminder_list-item_3yAmE{height:auto;min-height:40px}
.reminder_list-item_3yAmE .list-item-title{white-space:nowrap}

